trim.if:
UNION ALL
   SELECT 'factory_onboarding' AS source_type,s.id AS source_id,'01' AS module,CONCAT('入驻申请 ',CONVERT(s.application_no USING utf8mb4)) AS title,
     CONVERT(s.audit_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/status?id=',s.id) AS path,s.created_at AS created_at
   FROM factory_onboarding_audit s WHERE s.applicant_user_id=#{user}
   AND s.id=#{id}

UNION ALL
   SELECT 'rental_order' AS source_type,s.id AS source_id,'04' AS module,CONCAT('租赁订单 ',CONVERT(s.order_no USING utf8mb4)) AS title,
     CONVERT(s.order_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/order?id=''/pages/orders/detail?id=',s.id) AS path,s.created_at AS created_at
   FROM rental_order s WHERE s.factory_id=#{factory}s.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'payment_order' AS source_type,s.id AS source_id,'04' AS module,CONCAT('支付单 ',CONVERT(s.payment_no USING utf8mb4)) AS title,
     CONVERT(s.payment_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/payment/index?id=''/pages/payment/index?id=',s.id) AS path,s.created_at AS created_at
   FROM payment_order s WHERE NULL=#{factory}s.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'refund_order' AS source_type,s.id AS source_id,'04' AS module,CONCAT('退款单 ',CONVERT(s.refund_no USING utf8mb4)) AS title,
     CONVERT(s.refund_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/refund/detail?id=''/pages/refund/detail?id=',s.id) AS path,s.created_at AS created_at
   FROM refund_order s JOIN payment_order p ON p.id=s.payment_order_id WHERE NULL=#{factory}p.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'compensation_receivable' AS source_type,s.id AS source_id,'04' AS module,CONCAT('待缴偿还 ',CONVERT(s.receivable_no USING utf8mb4)) AS title,
     CONVERT(s.receivable_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/disputes?kind=compensation-receivables&id=''/pages/orders/disputes?kind=compensation-receivables&id=',s.id) AS path,s.created_at AS created_at
   FROM order_compensation_receivable s WHERE s.factory_id=#{factory}s.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'order_issue' AS source_type,s.id AS source_id,'05' AS module,CONCAT('订单问题 ',CONVERT(s.issue_no USING utf8mb4)) AS title,
     CONVERT(s.issue_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/fulfillment?id=''/pages/orders/issues?id=',o.id) AS path,s.created_at AS created_at
   FROM order_issue_report s JOIN rental_order o ON o.id=s.rental_order_id WHERE o.factory_id=#{factory}o.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'extension_application' AS source_type,s.id AS source_id,'04' AS module,CONCAT('延期申请 ',CONVERT(s.id USING utf8mb4)) AS title,
     CONVERT(s.extension_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/extensions?orderId=''/pages/orders/extensions?orderId=',s.rental_order_id) AS path,s.created_at AS created_at
   FROM order_extension_request s WHERE s.factory_id=#{factory}s.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'transport_order' AS source_type,s.id AS source_id,'05' AS module,CONCAT('运输段 ',CONVERT(o.order_no USING utf8mb4)) AS title,
     CONVERT(s.leg_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/fulfillment?id=''/pages/orders/fulfillment?id=',o.id) AS path,s.created_at AS created_at
   FROM order_transport_leg s JOIN rental_order o ON o.id=s.rental_order_id WHERE o.factory_id=#{factory}o.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'return_verification' AS source_type,s.id AS source_id,'05' AS module,CONCAT('归还核验 ',CONVERT(o.order_no USING utf8mb4)) AS title,
     CONVERT(s.check_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/fulfillment?id=''/pages/orders/fulfillment?id=',o.id) AS path,s.created_at AS created_at
   FROM order_return_check s JOIN rental_order o ON o.id=s.rental_order_id WHERE o.factory_id=#{factory}o.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'claim' AS source_type,s.id AS source_id,'06' AS module,CONCAT('索赔 ',CONVERT(s.claim_no USING utf8mb4)) AS title,
     CONVERT(s.claim_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/disputes?kind=claims&orderId=''/pages/orders/disputes?kind=claims&orderId=',o.id) AS path,s.created_at AS created_at
   FROM order_claim s JOIN rental_order o ON o.id=s.rental_order_id WHERE o.factory_id=#{factory}o.buyer_user_id=#{user}
   AND s.claim_status!='draft'


   AND s.id=#{id}

UNION ALL
   SELECT 'arbitration_case' AS source_type,s.id AS source_id,'06' AS module,CONCAT('仲裁 ',CONVERT(s.case_no USING utf8mb4)) AS title,
     CONVERT(s.case_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/disputes?kind=arbitrations&orderId=''/pages/orders/disputes?kind=arbitrations&orderId=',o.id) AS path,s.created_at AS created_at
   FROM arbitration_case s JOIN rental_order o ON o.id=s.rental_order_id WHERE o.factory_id=#{factory}o.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'custom_requirement' AS source_type,s.id AS source_id,'11' AS module,CONCAT('定制需求 ',CONVERT(s.requirement_no USING utf8mb4)) AS title,
     CONVERT(s.requirement_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/custom-detail?kind=requirements&id=''/pages/custom/detail?kind=requirements&id=',s.id) AS path,s.created_at AS created_at
   FROM custom_requirement s WHERE s.factory_id=#{factory}s.buyer_user_id=#{user}


   AND s.requirement_status!='draft'
   AND s.id=#{id}

UNION ALL
   SELECT 'custom_quote' AS source_type,s.id AS source_id,'11' AS module,CONCAT('定制报价 ',CONVERT(s.quote_no USING utf8mb4)) AS title,
     CONVERT(s.quote_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/custom-detail?kind=requirements&id=''/pages/custom/detail?kind=requirements&id=',s.requirement_id) AS path,s.created_at AS created_at
   FROM custom_quote s JOIN custom_requirement o ON o.id=s.requirement_id WHERE s.factory_id=#{factory}o.buyer_user_id=#{user}

   AND s.quote_status!='draft'

   AND s.id=#{id}

UNION ALL
   SELECT 'custom_order' AS source_type,s.id AS source_id,'11' AS module,CONCAT('定制订单 ',CONVERT(s.custom_order_no USING utf8mb4)) AS title,
     CONVERT(s.order_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/custom-detail?kind=orders&id=''/pages/custom/detail?kind=orders&id=',s.id) AS path,s.created_at AS created_at
   FROM custom_order s WHERE s.factory_id=#{factory}s.buyer_user_id=#{user}



   AND s.id=#{id}

UNION ALL
   SELECT 'custom_after_sale' AS source_type,s.id AS source_id,'11' AS module,CONCAT('定制售后 ',CONVERT(s.after_sale_no USING utf8mb4)) AS title,
     CONVERT(s.after_sale_status USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS status,CONCAT('/pages/factory/custom-detail?kind=orders&id=''/pages/custom/detail?kind=orders&id=',o.id) AS path,s.created_at AS created_at
   FROM custom_after_sale_request s JOIN custom_order o ON o.id=s.custom_order_id WHERE o.factory_id=#{factory}s.buyer_user_id=#{user}



   AND s.id=#{id}
